    "type": "object",
    "required": [
        "stack_api_key",
        "content_type_name",
        "entry_id"
    ],
    "properties": {
        "stack_api_key": {
            "title": "Select Stack",
            "type": "string",
            "description": "Select a stack to fetch the details of a single entry.",
            "default": "",
            "minLength": 3,
            "lookup": {
                "id": "get_stack_api_keys"
