const entry = input.entry;
let result = "";

const tag = ["faq"];

let tabsProcessed = new Array();

if (entry.hasOwnProperty("accordion")) {
    for (i = 0; i < entry.accordion.length; i++) {
        tabsProcessed.push(entry.accordion[i].tab_title);
        if (entry.accordion[i].hasOwnProperty("accordion_step")) {
            let steps = entry.accordion[i].accordion_step;
            for (stepIdx = 0; stepIdx < steps.length; stepIdx++) {
                if (result.length > 0){
                    result = result + ", ";
                }
                result = result + steps[stepIdx]._metadata.uid;
            }
        }
    }
}

//we need to pass a string with ids to remove from index
return result;"}

