{"params":[{"key":"entry","value":"{{2-2.entry}}"}],"code":"


const entry = input.entry;
let result = new Array();

const tag = ["faq"];

let tabsProcessed = new Array();

if (entry.hasOwnProperty("accordion")) {
    for (i = 0; i < entry.accordion.length; i++) {
        tabsProcessed.push(entry.accordion[i].tab_title);
        if (entry.accordion[i].hasOwnProperty("accordion_step")) {
            let steps = entry.accordion[i].accordion_step;
            for (stepIdx = 0; stepIdx < steps.length; stepIdx++) {
                let faq = new Object();
                faq.objectID = steps[stepIdx]._metadata.uid;
                faq.tag = tag;
                faq.type = "standard_page";
                faq.title = steps[stepIdx].accordion_heading;
                faq.short_description = steps[stepIdx].accordion_description;
                result.push(faq);       
            }
        }
    }
}

//due to automation issue which passes only first 3 elements of array to the next step
// we need to pass JSON of an object to be processed by Algolia
return JSON.stringify(result);"}

